use base64::Engine as _;
use eframe::egui;

// Official Avila Labs square mark supplied by Avila Labs, downsampled from the
// 2000 px master to 256 px with Lanczos filtering. The source texture remains
// large enough for crisp HiDPI rendering while keeping release binaries lean.
const AVILA_LABS_LOGO_PNG_BASE64: &str = "";

pub(crate) fn load_logo_texture(context: &egui::Context) -> Result<egui::TextureHandle, String> {
    let image = decode_logo()?;
    Ok(context.load_texture("avila-labs-logo", image, egui::TextureOptions::LINEAR))
}

fn decode_logo() -> Result<egui::ColorImage, String> {
    let png = base64::engine::general_purpose::STANDARD
        .decode(AVILA_LABS_LOGO_PNG_BASE64)
        .map_err(|error| format!("embedded Avila Labs logo is not valid base64: {error}"))?;
    let decoded = image::load_from_memory_with_format(&png, image::ImageFormat::Png)
        .map_err(|error| format!("embedded Avila Labs logo is not a valid PNG: {error}"))?
        .into_rgba8();
    let size = [decoded.width() as usize, decoded.height() as usize];
    Ok(egui::ColorImage::from_rgba_unmultiplied(
        size,
        decoded.as_raw(),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn official_logo_asset_is_embedded_at_hidpi_size() {
        let image = decode_logo().expect("official logo should decode");
        assert_eq!(image.size, [256, 256]);
        assert_eq!(image.pixels.len(), 256 * 256);
    }
}
